 bool keyboard(const MSG&msg){
  if(msg.message!=WM_KEYDOWN||GetAncestor(msg.hwnd,GA_ROOT)!=window_)return false;
  const bool ctrl=(GetKeyState(VK_CONTROL)&0x8000)!=0,shift=(GetKeyState(VK_SHIFT)&0x8000)!=0,alt=(GetKeyState(VK_MENU)&0x8000)!=0;
  if(alt)return false;
  if(ctrl&&shift){
   switch(msg.wParam){
    case 'F':command(FocusSearch);return true;
    case 'N':command(New);return true;
    case 'W':command(CloseTab);return true;
    case 'S':if(active())command(WinScp);return true;
    case 'C':case 'V':if(auto tab=active();tab&&(msg.hwnd==tab->host||IsChild(tab->host,msg.hwnd))){command(msg.wParam=='C'?Copy:Paste);return true;}break;
   }
  }
  if(ctrl&&msg.wParam==VK_TAB){if(!connections_.empty()){auto count=static_cast<int>(connections_.size());select_tab((std::max(0,active_)+(shift?count-1:1))%count);}return true;}
  if(!ctrl&&msg.wParam==VK_TAB&&(msg.hwnd==search_||msg.hwnd==tree_||msg.hwnd==tabs_||GetDlgCtrlID(msg.hwnd)==Connect||GetDlgCtrlID(msg.hwnd)==WinScp||GetDlgCtrlID(msg.hwnd)==NativePutty||GetDlgCtrlID(msg.hwnd)==CloseTab)){if(auto next=GetNextDlgTabItem(window_,msg.hwnd,shift))SetFocus(next);return true;}
  if(ctrl||shift)return false;
  if(msg.hwnd==search_){
   if(msg.wParam==VK_ESCAPE){SetWindowTextW(search_,L"");return true;}
   if(msg.wParam==VK_DOWN){SetFocus(tree_);return true;}
   if(msg.wParam==VK_RETURN){if(selected())command(Connect);return true;}
  }
  if(msg.hwnd==tree_){
   if(msg.wParam==VK_RETURN){if(selected())command(Connect);return true;}
   if(msg.wParam==VK_F2){if(selected())command(Edit);return true;}
   if(msg.wParam==VK_DELETE){command(Delete);return true;}
  }
  return false;
 }
