  TerminalSize size;if(!compatibility){auto raw=tab.get();try{tab->terminal->create(tab->host,[raw](std::string_view bytes){raw->process.send(bytes);});size=tab->terminal->resize(800,500);}catch(...){if(front_choice_!=FrontAuto)throw;tab->terminal.reset();tab->terminal=std::make_unique<TerminalControl>();compatibility=true;}}
