  if(compatibility){tab->conemu=std::make_unique<ConEmuFrontend>();tab->conemu->start(tab->host,components_.directory(),executable,arguments,tab->pipe.get());}else{tab->process.start(tab->host,executable,arguments,size);if(tab->pipe)tab->pipe->bind(tab->process.process_handle(),tab->process.pid());}
